// Exhaustive self-checking testbench (generated by LSE)
// Run: iverilog -o sim tb_bcd7seg.v bcd7seg.v && vvp sim
`timescale 1ns / 1ps
module tb_bcd7seg;
    reg  [3:0] x;
    wire [6:0] y;
    integer errors = 0;
    bcd7seg dut (.D3(x[3]), .D2(x[2]), .D1(x[1]), .D0(x[0]), .a(y[0]), .b(y[1]), .c(y[2]), .d(y[3]), .e(y[4]), .f(y[5]), .g(y[6]));

    // compare y with the expected value, ignoring don't-care bits (care = 0)
    task check(input [6:0] expected, input [6:0] care);
        if (((y ^ expected) & care) !== 0) begin
            $display("MISMATCH x=%b y=%b expected=%b", x, y, expected);
            errors = errors + 1;
        end
    endtask

    initial begin
        x = 4'd0; #1 check(7'b0111111, 7'b1111111);
        x = 4'd1; #1 check(7'b0000110, 7'b1111111);
        x = 4'd2; #1 check(7'b1011011, 7'b1111111);
        x = 4'd3; #1 check(7'b1001111, 7'b1111111);
        x = 4'd4; #1 check(7'b1100110, 7'b1111111);
        x = 4'd5; #1 check(7'b1101101, 7'b1111111);
        x = 4'd6; #1 check(7'b1111101, 7'b1111111);
        x = 4'd7; #1 check(7'b0000111, 7'b1111111);
        x = 4'd8; #1 check(7'b1111111, 7'b1111111);
        x = 4'd9; #1 check(7'b1101111, 7'b1111111);
        x = 4'd10; #1 check(7'b0000000, 7'b0000000);
        x = 4'd11; #1 check(7'b0000000, 7'b0000000);
        x = 4'd12; #1 check(7'b0000000, 7'b0000000);
        x = 4'd13; #1 check(7'b0000000, 7'b0000000);
        x = 4'd14; #1 check(7'b0000000, 7'b0000000);
        x = 4'd15; #1 check(7'b0000000, 7'b0000000);
        if (errors == 0) $display("PASS: all 16 input combinations match");
        else $display("FAIL: %0d mismatches", errors);
        $finish;
    end
endmodule
